/**
 * satisfaction-pulse.tsx
  *
   * Recommendation #5 — One-Tap Satisfaction Pulse on Tool Result Pages
    *
     * Problem: The feedback widget is great but requires users to seek it out.
      * We capture zero sentiment data at the moment of highest motivation —
       * right after someone gets a scan result.
        *
         * Solution: A compact, unobtrusive thumbs-up/down component that appears
          * at the bottom of every tool result. One tap is all it takes. An optional
           * "tell us more" expands for users who want to elaborate.
            *
             * Usage:
              *   import { SatisfactionPulse } from "@/components/satisfaction-pulse";
               *
                *   // At the bottom of any tool result component:
                 *   <SatisfactionPulse toolName="scam-checker" resultId={scan.id} />
                  *
                   * The component posts to POST /api/satisfaction-pulse with:
                    *   { toolName, resultId, rating: "positive"|"negative", comment?, page }
                     */

                     "use client";

                     import { useState } from "react";
                     import { useMutation } from "@tanstack/react-query";
                     import { ThumbsUp, ThumbsDown, MessageSquarePlus, CheckCircle2 } from "lucide-react";
                     import { Button } from "@/components/ui/button";
                     import { Textarea } from "@/components/ui/textarea";
                     import { apiRequest } from "@/lib/queryClient";
                     import { useToast } from "@/hooks/use-toast";

                     type Rating = "positive" | "negative";

                     interface SatisfactionPulseProps {
                       /** Identifier for the tool being rated, e.g. "scam-checker", "voice-check" */
                         toolName: string;
                           /** Optional ID of the specific scan/result so we can correlate feedback */
                             resultId?: string;
                               /** Custom prompt text */
                                 prompt?: string;
                                   /** Additional className on the wrapper */
                                     className?: string;
                                     }

                                     interface PulsePayload {
                                       toolName: string;
                                         resultId?: string;
                                           rating: Rating;
                                             comment?: string;
                                               page: string;
                                                 submittedAt: string;
                                                 }

                                                 export function SatisfactionPulse({
                                                   toolName,
                                                     resultId,
                                                       prompt = "Was this result helpful?",
                                                         className = "",
                                                         }: SatisfactionPulseProps) {
                                                           const [rating, setRating] = useState<Rating | null>(null);
                                                             const [showComment, setShowComment] = useState(false);
                                                               const [comment, setComment] = useState("");
                                                                 const [done, setDone] = useState(false);
                                                                   const { toast } = useToast();

                                                                     const pulseMutation = useMutation({
                                                                         mutationFn: async (data: PulsePayload) => {
                                                                               const res = await apiRequest("POST", "/api/satisfaction-pulse", data);
                                                                                     return res.json();
                                                                                         },
                                                                                             onSuccess: () => {
                                                                                                   setDone(true);
                                                                                                       },
                                                                                                           onError: () => {
                                                                                                                 // Silent fail — don't interrupt the user's experience for analytics
                                                                                                                       setDone(true);
                                                                                                                           },
                                                                                                                             });
                                                                                                                             
                                                                                                                               const handleRating = (selected: Rating) => {
                                                                                                                                   setRating(selected);
                                                                                                                                       // For positive: submit immediately; for negative: show comment box first
                                                                                                                                           if (selected === "positive") {
                                                                                                                                                 pulseMutation.mutate({
                                                                                                                                                         toolName,
                                                                                                                                                                 resultId,
                                                                                                                                                                         rating: selected,
                                                                                                                                                                                 page: typeof window !== "undefined" ? window.location.pathname : "",
                                                                                                                                                                                         submittedAt: new Date().toISOString(),
                                                                                                                                                                                               });
                                                                                                                                                                                                     toast({
                                                                                                                                                                                                             title: "Thanks for the feedback!",
                                                                                                                                                                                                                     description: "Glad it was helpful.",
                                                                                                                                                                                                                             duration: 3000,
                                                                                                                                                                                                                                   });
                                                                                                                                                                                                                                       } else {
                                                                                                                                                                                                                                             setShowComment(true);
                                                                                                                                                                                                                                                 }
                                                                                                                                                                                                                                                   };
                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                     const handleSubmitWithComment = () => {
                                                                                                                                                                                                                                                         pulseMutation.mutate({
                                                                                                                                                                                                                                                               toolName,
                                                                                                                                                                                                                                                                     resultId,
                                                                                                                                                                                                                                                                           rating: rating!,
                                                                                                                                                                                                                                                                                 comment: comment.trim() || undefined,
                                                                                                                                                                                                                                                                                       page: typeof window !== "undefined" ? window.location.pathname : "",
                                                                                                                                                                                                                                                                                             submittedAt: new Date().toISOString(),
                                                                                                                                                                                                                                                                                                 });
                                                                                                                                                                                                                                                                                                     toast({
                                                                                                                                                                                                                                                                                                           title: "Feedback received.",
                                                                                                                                                                                                                                                                                                                 description: "We'll use this to improve. Thank you.",
                                                                                                                                                                                                                                                                                                                       duration: 4000,
                                                                                                                                                                                                                                                                                                                           });
                                                                                                                                                                                                                                                                                                                             };
                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                               if (done && rating === "positive") {
                                                                                                                                                                                                                                                                                                                                   return (
                                                                                                                                                                                                                                                                                                                                         <div className={`flex items-center gap-2 text-green-400 text-xs ${className}`}>
                                                                                                                                                                                                                                                                                                                                                 <CheckCircle2 className="h-3.5 w-3.5" />
                                                                                                                                                                                                                                                                                                                                                         <span>Thanks — glad it helped!</span>
                                                                                                                                                                                                                                                                                                                                                               </div>
                                                                                                                                                                                                                                                                                                                                                                   );
                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                       if (done && rating === "negative") {
                                                                                                                                                                                                                                                                                                                                                                           return (
                                                                                                                                                                                                                                                                                                                                                                                 <div className={`flex items-center gap-2 text-teal-400 text-xs ${className}`}>
                                                                                                                                                                                                                                                                                                                                                                                         <CheckCircle2 className="h-3.5 w-3.5" />
                                                                                                                                                                                                                                                                                                                                                                                                 <span>Noted — we'll work on it.</span>
                                                                                                                                                                                                                                                                                                                                                                                                       </div>
                                                                                                                                                                                                                                                                                                                                                                                                           );
                                                                                                                                                                                                                                                                                                                                                                                                             }
                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                               return (
                                                                                                                                                                                                                                                                                                                                                                                                                   <div className={`${className}`}>
                                                                                                                                                                                                                                                                                                                                                                                                                         {/* Primary pulse row */}
                                                                                                                                                                                                                                                                                                                                                                                                                               {!showComment && (
                                                                                                                                                                                                                                                                                                                                                                                                                                       <div className="flex items-center gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                 <span className="text-gray-500 text-xs">{prompt}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                           <div className="flex items-center gap-1.5">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                       <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     onClick={() => handleRating("positive")}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   disabled={pulseMutation.isPending}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 aria-label="Helpful"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               className={`flex items-center gap-1 px-2.5 py-1.5 rounded-lg border text-xs transition-all duration-150 ${
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               rating === "positive"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ? "border-green-500/40 bg-green-500/10 text-green-400"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   : "border-white/10 text-gray-500 hover:border-green-500/30 hover:text-green-400 hover:bg-green-500/5"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           <ThumbsUp className="h-3 w-3" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         <span>Yes</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               onClick={() => handleRating("negative")}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             disabled={pulseMutation.isPending}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           aria-label="Not helpful"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         className={`flex items-center gap-1 px-2.5 py-1.5 rounded-lg border text-xs transition-all duration-150 ${
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         rating === "negative"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           ? "border-red-500/40 bg-red-500/10 text-red-400"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             : "border-white/10 text-gray-500 hover:border-red-500/30 hover:text-red-400 hover:bg-red-500/5"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     <ThumbsDown className="h-3 w-3" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   <span>No</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             {/* Expanded comment box for negative ratings */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   {showComment && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           <div className="mt-3 space-y-2 max-w-md">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     <div className="flex items-center gap-1.5 text-xs text-gray-400">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 <MessageSquarePlus className="h-3.5 w-3.5 text-teal-400" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <span>What went wrong? (optional — helps us fix it faster)</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 <Textarea
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             value={comment}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         onChange={(e) => setComment(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     placeholder="e.g. The result said the link was safe but it looked suspicious to me..."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 className="bg-[#0a1628] border-white/10 text-white placeholder:text-gray-600 text-xs resize-none min-h-[72px]"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             maxLength={500}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 <div className="flex items-center gap-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <Button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           size="sm"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         onClick={handleSubmitWithComment}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       disabled={pulseMutation.isPending}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     className="bg-teal-600 hover:bg-teal-500 text-white text-xs h-7 px-3"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               {pulseMutation.isPending ? "Sending..." : "Send feedback"}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           </Button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     onClick={() => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     setShowComment(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     handleSubmitWithComment();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 className="text-gray-600 hover:text-gray-400 text-xs transition-colors"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           Skip
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
